return ['x-generator'=>'GlotPress/4.0.3','translation-revision-date'=>'2026-06-02 16:32:47+0000','plural-forms'=>'nplurals=1; plural=0;','project-id-version'=>'Plugins - WP Consent API - Stable (latest release)','language'=>'ja_JP','messages'=>['WordPress Contributors'=>'WordPress コントリビューター','Missing consent category. A functional, preferences, statistics-anonymous, statistics or marketing category should be passed when using wp_setcookie.'=>'同意カテゴリが指定されていません。wp_setcookie を使用する際は、機能性情報 / 設定情報 / 匿名化された統計情報 / 統計情報 / マーケティング情報、のいずれかのカテゴリを指定する必要があります。','Consent Level API to read and register the current consent level for cookie management and improving compliance with privacy laws.'=>'Cookie 管理に関する現在の同意レベルを確認および登録し、プライバシー関連法規への準拠を強化するための Consent Level API。','WP Consent API'=>'WP Consent API','WP Consent API test'=>'WP Consent API テスト','https://github.com/WordPress/wp-consent-level-api'=>'https://github.com/WordPress/wp-consent-level-api','https://wordpress.org/plugins/wp-consent-api'=>'https://wordpress.org/plugins/wp-consent-api','Compliance'=>'準拠','All plugins have declared to use the Consent API'=>'すべての プラグイン で、Consent API を使用することが宣言されています','All plugins have declared in their code that they are following the guidelines from the WP Consent API. When used in combination with a Cookie Management plugin, this will improve compliancy for your site.'=>'すべてのプラグインは、それぞれのコード内で、WP Consent API のガイドラインに準拠していることを宣言しています。Cookie 管理プラグインと組み合わせて使用することで、あなたのサイトにおけるコンプライアンスが向上します。','Not all plugins have declared to follow Consent API guidelines. Please contact the developer.'=>'すべてのプラグインが Consent API ガイドラインに準拠していると宣言しているわけではありません。開発者にお問い合わせください。','One or more plugins are not conforming to the Consent API.'=>'1つ以上のプラグインが、Consent API に準拠していません。','%s is a singleton class and you cannot create a second instance.'=>'%s はシングルトンクラスであり、2つ目のインスタンスを作成できません。']];